CREATE TABLE public.parts_consumption (
  id uuid DEFAULT gen_random_uuid() NOT NULL,
  organisation_id uuid DEFAULT public.app_current_org() NOT NULL,
  country text,
  issue_number text,
  work_order_no text,
  txn_date text,
  asset_code text,
  asset_description text,
  asset_type text,
  store_code text,
  cost_center text,
  item_code text,
  qty text,
  item_description text,
  value_amount text,
  spare_parts_amount text,
  tyre_amount text,
  oil_amount text,
  total_amount text,
  source_row text,
  line_cost numeric,
  cost_category text,
  tyre_cost numeric DEFAULT 0,
  spare_cost numeric DEFAULT 0,
  oil_cost numeric DEFAULT 0,
  created_at timestamp with time zone DEFAULT now() NOT NULL,
  event_date date,
  qty_n numeric,
  brand text,
  import_uid text,
  currency text,
  fx_rate_to_base numeric,
  region text,
  branch text,
  project text,
  department text,
  site text,
  uom text,
  unit_cost numeric,
  supplier text,
  source_system text,
  approved_by uuid,
  classified_by text,
  classify_confidence numeric,
  erp_bucket text GENERATED ALWAYS AS (
CASE
    WHEN (COALESCE(public._to_num(tyre_amount), (0)::numeric) > (0)::numeric) THEN 'tyre'::text
    WHEN (COALESCE(public._to_num(oil_amount), (0)::numeric) > (0)::numeric) THEN 'oil'::text
    WHEN (COALESCE(public._to_num(spare_parts_amount), (0)::numeric) > (0)::numeric) THEN 'spare'::text
    ELSE NULL::text
END) STORED,
  filled_cost numeric,
  filled_cost_basis text,
  reupload_hash text GENERATED ALWAYS AS (md5(((((((((((((((((((COALESCE((organisation_id)::text, chr(31)) || chr(30)) || COALESCE(country, chr(31))) || chr(30)) || COALESCE(((event_date - '1970-01-01'::date))::text, chr(31))) || chr(30)) || COALESCE(issue_number, chr(31))) || chr(30)) || COALESCE(work_order_no, chr(31))) || chr(30)) || COALESCE(item_code, chr(31))) || chr(30)) || COALESCE(qty, chr(31))) || chr(30)) || COALESCE(value_amount, chr(31))) || chr(30)) || COALESCE(store_code, chr(31))) || chr(30)) || COALESCE(cost_center, chr(31))))) STORED
) WITH (autovacuum_vacuum_scale_factor=0.02, autovacuum_vacuum_insert_scale_factor=0.02, autovacuum_analyze_scale_factor=0.02);
-- @@
