  file_name text NOT NULL,
  file_hash text,
  file_size_bytes bigint,
  storage_path text,
  sheet_name text,
  report_date date,
  status text DEFAULT 'previewed'::text NOT NULL,
  uploaded_by uuid,
  uploaded_by_name text,
  uploaded_at timestamp with time zone DEFAULT now() NOT NULL,
  confirmed_by uuid,
  confirmed_by_name text,
  confirmed_at timestamp with time zone,
  cancelled_by uuid,
  cancelled_at timestamp with time zone,
  total_rows integer DEFAULT 0 NOT NULL,
  new_count integer DEFAULT 0 NOT NULL,
  updated_count integer DEFAULT 0 NOT NULL,
  unchanged_count integer DEFAULT 0 NOT NULL,
  removed_count integer DEFAULT 0 NOT NULL,
  closed_count integer DEFAULT 0 NOT NULL,
  invalid_count integer DEFAULT 0 NOT NULL,
  duplicate_count integer DEFAULT 0 NOT NULL,
  previous_active_count integer,
  header_map jsonb DEFAULT '{}'::jsonb NOT NULL,
  unmapped_headers text[] DEFAULT '{}'::text[] NOT NULL,
  duplicate_of_upload_id uuid,
  duplicate_acknowledged boolean DEFAULT false NOT NULL,
  failure_reason text,
  notes text,
  kept_count integer DEFAULT 0 NOT NULL
);
